]

h, w = len(grid), len(grid[0])

# Find all cells in components that touch the grid edge
def get_edge_touching_components():
    visited = set()
    edge_colors = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 and (r,c) not in visited:
                color = grid[r][c]
                component = []
                queue = deque([(r,c)])
                visited.add((r,c))

                # Check if starts at edge
                is_edge = rr == 0 or rr == h-1 or cc == 0 or cc == w-1
                start_at_edge = r in (0, h-1) or c in (0, w-1)

                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == color and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                queue.append((nr,nc))

                # Check if any cell in component touches edge
                for cr, cc in component:
