for r in range(h):
    row_out = []
    for c in range(w):
        if grid[r][c] != 5 and (r,c) not in visited:
            color = grid[r][c]
            if color in edge_colors:
                component_cells = []
                queue = deque([(r,c)])
                visited.add((r,c))

                while queue:
                    cr, cc = queue.popleft()
                    component_cells.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == color and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                queue.append((nr,nc))
            else:
                pass

        # For simplicity, just check if this cell's color is an edge color
        # And it's either at edge or connected to something at edge
        if grid[r][c] != 5:
            # BFS to find if connected to edge
            local_visited = set()
            queue = deque([(r,c)])
            local_visited.add((r,c))
            reaches_edge = False

            while queue and not reaches_edge:
                cr, cc = queue.popleft()
                if cr in (0, h-1) or cc in (0, w-1):
                    reaches_edge = True

                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
